+		t.Fatal("Verdict update succeeded")
+	}
+	if _, err := f.db.ExecContext(f.ctx, `DELETE FROM verdicts WHERE task_id=?`, f.review); err == nil {
+		t.Fatal("Verdict delete succeeded")
+	}
+}
