+		}
+		if outcome == "findings" {
+			verdict.Blocking, err = countBlockingReviewFindingsTx(ctx, tx, changeTaskID, verdict.Repository, input.Findings.BlockAt)
+			if err != nil {
+				rows.Close()
+				return err
+			}
+		}
